function authClose(){$("authm").style.display="none"}
function toast(t){const e=document.createElement("div");e.textContent=t;e.style.cssText="position:fixed;bottom:70px;left:50%;transform:translateX(-50%);z-index:60;background:#111;color:#fff;padding:10px 18px;border-radius:99px;font-size:14px;box-shadow:0 6px 20px rgba(0,0,0,.35)";document.body.append(e);setTimeout(()=>e.remove(),4500)}
function loadScript(src){return new Promise((ok,no)=>{const s=document.createElement("script");s.src=src;s.onload=ok;s.onerror=no;document.head.append(s)})}
