function fitText(g,txt,maxW,px,min,weight){px=px||48;do{g.font=`${weight||"bold"} ${px}px ${FF()}`;px-=2}while(g.measureText(txt).width>maxW&&px>(min||18));return g.measureText(txt).width<=maxW}
