// ---------- המשך עבודה מהטיוטה האחרונה (גם בלי התחברות) ----------
(function(){
  const home=document.querySelector("#home .box");if(!home)return;
  let raw=null,ts=0;try{raw=localStorage.getItem("trip3d_p");ts=+localStorage.getItem("trip3d_pt")||0}catch(e){}
  if(!raw)return;let pj;try{pj=JSON.parse(raw)}catch(e){return}
  if(ts&&Date.now()-ts>45*864e5)return;
  const name=String((pj.f&&pj.f.trip)||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),tn=(typeof TOOLNAME!="undefined"&&TOOLNAME[pj.tool])||"",when=ts?new Date(ts).toLocaleString(LANG=="en"?"en-GB":"he-IL",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}):"";
  const d=document.createElement("div");d.id="resume";d.setAttribute("role","region");d.setAttribute("aria-label",L_("טיוטה שמורה","Saved draft"));d.style.cssText="margin:14px 0;padding:12px 14px;border:2px solid var(--ac);border-radius:14px;background:var(--card);display:flex;gap:10px;align-items:center;flex-wrap:wrap";
  d.innerHTML=`<div style="flex:1;min-width:180px"><b>↩ ${L_("המשיכו מאיפה שעצרתם","Continue where you left off")}</b><br><span class="hint">${[tn,name,when].filter(Boolean).join(" · ")}</span></div><button class="go" id="rs_go" type="button" style="margin:0">${L_("המשך","Continue")}</button><button id="rs_no" type="button">${L_("מחיקת הטיוטה","Discard")}</button>`;
  const anchor=$("banner");anchor?anchor.after(d):home.prepend(d);
  $("rs_go").onclick=()=>{try{putProj(pj);$("home").style.display="none";$("intro").style.display="none";toast(L_("הטיוטה נטענה","Draft loaded"))}catch(e){toast(L_("לא הצלחתי לטעון את הטיוטה","Couldn't load the draft"))}};
  $("rs_no").onclick=()=>{try{localStorage.removeItem("trip3d_p");localStorage.removeItem("trip3d_pt")}catch(e){}d.remove()};
})();
